head.script:
scwin.test = function(row, col) {
    var obj = {};
    if (row == 0) {
        obj.increment = 2;
        obj.minValue = 0;
        obj.maxValue = 10;
        return obj;
    } else if (row == 1) {
        obj.increment = 4;
        obj.minValue = 0;
        obj.maxValue = 20;
        return obj;
    } else if (row == 2) {
        obj.increment = 8;
        obj.minValue = 0;
        obj.maxValue = 40;
        return obj;
    }
};
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_0_1').hasClass('gridBodyDefault_spinner') == true;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_1_1').hasClass('gridBodyDefault_spinner') == true;
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_2_1').hasClass('gridBodyDefault_spinner') == true;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gridView1_cell_0_1').getAttribute(dataInputType) == 'spinner'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gridView1_cell_1_1').getAttribute(dataInputType) == 'spinner'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gridView1_cell_2_1').getAttribute(dataInputType) == 'spinner'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 30-Jan-2018
    //end
    window.dataInputType = WebSquare.util.getDataPrefix("inputtype");
}
